const cv = ($json.cv_url || '') + '';
const isDrive = cv.indexOf('drive.google.com') !== -1 || cv.indexOf('docs.google.com') !== -1;
let id = '';
if (isDrive) {
  if (cv.indexOf('/d/') !== -1) { id = cv.split('/d/')[1].split('/')[0].split('?')[0]; }
  else if (cv.indexOf('id=') !== -1) { id = cv.split('id=')[1].split('&')[0]; }
}
return { json: Object.assign({}, $json, { driveFileId: id || 'SEM_ARQUIVO', temDrive: !!id }) };

const cand = $('Extrair Drive ID').all().map(i => i.json);
const cur = $input.all();
const MAX_CV = 25;
const fileParts = [];
function tcase(s) {
  return s.split(' ').map(function (w) { return w ? (w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()) : w; }).join(' ');
}
for (let i = 0; i < cand.length; i++) {
  const c = cand[i];
  const it = cur[i] || {};
  const bkeys = it.binary ? Object.keys(it.binary) : [];
  const meta = bkeys.length ? it.binary[bkeys[0]] : null;
  const mt = meta && meta.mimeType ? meta.mimeType : '';
  const okType = mt.indexOf('application/pdf') === 0 || mt.indexOf('image/') === 0;
  const hasErr = it.json && it.json.error ? true : false;
  let b64 = '';
  if (meta && okType && !hasErr && fileParts.length < MAX_CV) {
    try {
      const buff = await this.helpers.getBinaryDataBuffer(i, bkeys[0]);
      b64 = buff ? buff.toString('base64') : '';
    } catch (e) { b64 = ''; }
  }
  const raw = (c.area_interesse || '').split(',').map(function (s) { return tcase(s.trim()); }).filter(function (s) { if (!s.length) return false; const t = s.toLowerCase(); return t.indexOf('estag') !== 0 && t.indexOf('está') !== 0; });
  // >>> EDITE: area (em minusculas) -> grupo/vaga onde ela aparece.
  const MAP_GRUPO = { 'marketing': 'Comercial' };
  function grupoVaga(a) { return MAP_GRUPO[a.toLowerCase()] || a; }
  const vlist = raw.length ? Array.from(new Set(raw.map(grupoVaga))) : ['Nao informado'];
  c._vaga = vlist[0];
  c._areaMarcada = raw.length ? raw[0] : 'Nao informado';
  c._outras = vlist.slice(1);
  c._cvLido = !!b64;
  if (b64) {
    fileParts.push({ text: '\n=== Curriculo (n ' + (i + 1) + ') de ' + (c.nome || 'candidato') + ' ===' });
    fileParts.push({ inlineData: { mimeType: mt, data: b64 } });
  }
}
const dados = cand.map(function (c, idx) {
  return {
    n: idx + 1, nome: c.nome, cidade: c.cidade, idade: c.idade, foto: c.foto || null,
    vaga: c._vaga, area_marcada: c._areaMarcada, outras_areas_marcadas: c._outras, cv_lido: c._cvLido, cv_url: c.cv_url,
    escolaridade: c.escolaridade, formacao: c.formacao, instituicao: c.instituicao, esta_estudando: c.esta_estudando,
    experiencia: c.experiencia, cursos: c.cursos, certificacoes: c.certificacoes,
    pretensao_salarial: c.pretensao_salarial, disponivel_mudanca: c.disponivel_mudanca, cnh: c.cnh
  };
});
// >>> EDITE AQUI: areas da Young (usadas so no campo onde_agrega).
const areasYoung = ['Comercial / Vendas','Engenharia e Obras','Projetos e Licenciamento','Captacao e Novos Negocios','Pos-venda','Financeiro e Cobranca','RH / Gente (recrutamento e contratacoes)','Administrativo, Registros e Documentacao','Marketing','TI / Sistemas'];
const instrucao = [
  'Voce e analista de RH da Young Empreendimentos (incorporadora e loteadora).',
  'Analise os candidatos e RETORNE APENAS JSON valido (sem texto fora do JSON e sem cercas de codigo) neste formato:',
  '{ "vagas": [ { "vaga": "<nome exato da vaga>", "candidatos": [ { "n": <n>, "nivel": "Efetivo|Estagio|Jovem Aprendiz", "posicao": <inteiro, 1 = topo>, "ranking_justificativa": "<curto; vazio se so 1 na vaga>", "perfil": "<2 a 3 frases>", "onde_agrega": "<1 a 2 frases>" } ] } ] }',
  'Regras:',
  '- Cada candidato aparece em UMA UNICA vaga: use o campo "vaga" (ja vem agrupado; ex.: Marketing entra em Comercial). NAO repita o candidato em outras vagas.',
  '- Classifique o "nivel" com base em IDADE e EXPERIENCIA (e escolaridade/esta_estudando): "Jovem Aprendiz" (muito jovem, sem/pouca experiencia), "Estagio" (estudante/estagiario), "Efetivo" (perfil para cargo efetivo, com formacao/experiencia).',
  '- Dentro de cada vaga defina "posicao" (1 = topo): PRIMEIRO os mais qualificados; a ordem segue Efetivo, depois Estagio, depois Jovem Aprendiz; dentro do mesmo nivel, do mais qualificado ao menos. Se houver so 1 candidato, posicao=1 e ranking_justificativa vazio.',
  '- "perfil": resuma experiencia, formacao, cursos e certificacoes. Se houver curriculo anexado (arquivo com o mesmo n), baseie-se PRINCIPALMENTE nele.',
  '- "onde_agrega": considere a "area_marcada" (o interesse real da pessoa, ex.: Marketing) para indicar a atuacao; pode apontar OUTRA area da Young se o perfil encaixar melhor. Areas da Young: ' + areasYoung.join('; ') + '.',
  '- Use o "n" exatamente como veio. Nao invente dados.',
  'DADOS (JSON):',
  JSON.stringify(dados)
].join('\n');
return [{ json: { dados: dados, geminiBody: { contents: [{ parts: [{ text: instrucao }].concat(fileParts) }], generationConfig: { temperature: 0.3, maxOutputTokens: 32768, thinkingConfig: { thinkingBudget: 0 }, responseMimeType: 'application/json' } } } }];

const src = $('Montar prompt (Gemini)').first().json;
const dados = src.dados || [];
const byN = {};
dados.forEach(function (d) { byN[d.n] = d; });
let ai = { vagas: [] };
try { ai = JSON.parse($json.candidates[0].content.parts[0].text); } catch (e) { ai = { vagas: [] }; }
const total = dados.length;
const lidos = dados.filter(function (d) { return d.cv_lido; }).length;
const LARANJA = '#fe5009';
function esc(s) { return String(s == null ? '' : s).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;'); }
function isFoto(u) { return typeof u === 'string' && u.indexOf('supabase.co/storage') !== -1; }
function iniciais(nome) { const p = String(nome || '?').trim().split(' ').filter(Boolean); return ((p[0] || '?').charAt(0) + (p.length > 1 ? p[p.length - 1].charAt(0) : '')).toUpperCase(); }
function avatar(d) {
  if (isFoto(d.foto)) { return '<img src="' + esc(d.foto) + '" width="52" height="52" alt="" style="width:52px;height:52px;border-radius:50%;object-fit:cover;display:block;border:2px solid #f0f0f0;">'; }
  return '<div style="width:52px;height:52px;border-radius:50%;background:' + LARANJA + ';color:#fff;font-weight:700;font-size:18px;line-height:52px;text-align:center;">' + esc(iniciais(d.nome)) + '</div>';
}
function selo(d) {
  return d.cv_lido
    ? '<span style="background:#e6f4ea;color:#1e7e34;font-size:11px;font-weight:700;padding:2px 8px;border-radius:10px;">CV lido</span>'
    : '<span style="background:#fdecea;color:#b3261e;font-size:11px;font-weight:700;padding:2px 8px;border-radius:10px;">so link</span>';
}
function nivelBadge(nv) {
  if (!nv) return '';
  const s = String(nv).toLowerCase();
  let cor = '#555', bg = '#eee';
  if (s.indexOf('efet') !== -1) { cor = '#0b57d0'; bg = '#e8f0fe'; }
  else if (s.indexOf('estag') !== -1 || s.indexOf('está') !== -1) { cor = '#6a1b9a'; bg = '#f3e8fd'; }
  else if (s.indexOf('aprendiz') !== -1) { cor = '#00695c'; bg = '#e0f2f1'; }
  return '<span style="background:' + bg + ';color:' + cor + ';font-size:11px;font-weight:700;padding:2px 8px;border-radius:10px;margin-left:6px;">' + esc(nv) + '</span>';
}
function card(item, grupo) {
  const d = byN[item.n] || {};
  const sub = [d.cidade, (d.idade ? d.idade + ' anos' : null)].filter(Boolean).join(' - ');
  const at = (d.area_marcada && d.area_marcada !== 'Nao informado' && d.area_marcada !== grupo) ? d.area_marcada : null;
  const atTag = at ? ' &middot; <strong style="color:#6a1b9a;">Atuacao: ' + esc(at) + '</strong>' : '';
  const pos = item.posicao ? '<span style="background:' + LARANJA + ';color:#fff;font-weight:700;font-size:12px;width:22px;height:22px;line-height:22px;text-align:center;border-radius:50%;display:inline-block;">' + esc(item.posicao) + '</span> ' : '';
  const link = (!d.cv_lido && d.cv_url) ? ' &middot; <a href="' + esc(d.cv_url) + '" style="color:' + LARANJA + ';">abrir CV</a>' : '';
  return '<table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #eee;border-radius:10px;margin:8px 0;background:#fff;"><tr>'
    + '<td width="64" valign="top" style="padding:12px;">' + avatar(d) + '</td>'
    + '<td valign="top" style="padding:12px 12px 12px 0;font-family:Arial,sans-serif;color:#222;">'
    + '<div style="font-size:15px;font-weight:700;">' + pos + esc(d.nome || 'Candidato') + ' ' + selo(d) + nivelBadge(item.nivel) + '</div>'
    + ((sub || at || link) ? '<div style="font-size:12px;color:#777;margin-top:2px;">' + esc(sub) + atTag + link + '</div>' : '')
    + (item.perfil ? '<div style="font-size:13px;margin-top:8px;"><strong>Perfil:</strong> ' + esc(item.perfil) + '</div>' : '')
    + (item.onde_agrega ? '<div style="font-size:13px;margin-top:4px;"><strong>Onde agrega:</strong> ' + esc(item.onde_agrega) + '</div>' : '')
    + (item.ranking_justificativa ? '<div style="font-size:12px;color:#555;margin-top:4px;font-style:italic;">' + esc(item.ranking_justificativa) + '</div>' : '')
    + '</td></tr></table>';
}
let bodyHtml = '';
(ai.vagas || []).forEach(function (v) {
  const cands = (v.candidatos || []).slice().sort(function (a, b) { return (a.posicao || 99) - (b.posicao || 99); });
  bodyHtml += '<h2 style="font-family:Arial,sans-serif;font-size:16px;color:#222;border-left:4px solid ' + LARANJA + ';padding-left:8px;margin:22px 0 6px;">' + esc(v.vaga) + ' <span style="color:#999;font-weight:400;font-size:13px;">(' + cands.length + ')</span></h2>';
  cands.forEach(function (item) { bodyHtml += card(item, v.vaga); });
});
if (!bodyHtml) { bodyHtml = '<p style="font-family:Arial,sans-serif;color:#777;">Sem candidatos para exibir.</p>'; }
const html = '<div style="max-width:680px;margin:0 auto;background:#f6f6f6;padding:0 0 20px;">'
  + '<div style="background:' + LARANJA + ';color:#fff;padding:20px 24px;font-family:Arial,sans-serif;">'
  + '<div style="font-size:20px;font-weight:800;">Young Talents</div>'
  + '<div style="font-size:13px;opacity:.9;">Novos candidatos da semana</div>'
  + '</div>'
  + '<div style="padding:16px 24px;font-family:Arial,sans-serif;color:#333;">'
  + '<div style="background:#fff;border-radius:10px;padding:12px 16px;font-size:14px;"><strong>' + total + '</strong> candidato(s) &nbsp;|&nbsp; <strong>' + lidos + '</strong> com CV lido</div>'
  + bodyHtml
  + '<p style="font-size:11px;color:#999;margin-top:20px;">Gerado automaticamente pelo Young Talents.</p>'
  + '</div></div>';
const subject = '📋 Novos candidatos da semana - Young Talents (' + $now.toFormat('dd/LL/yyyy') + ')';
return [{ json: { html: html, subject: subject, total: total, lidos: lidos } }];
